using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;

Console.WriteLine("Research Agent Starting...");

var topic = args.Length > 0 ? string.Join(" ", args) : "recent advances in quantum computing";
Console.WriteLine($"Researching topic: {topic}\n");

// Configure the AI chat client (expects OPENAI_API_KEY env var)
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable.");
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient innerClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient();

// Wrap with tool support
var researchTools = new ResearchTools();
IChatClient agent = new ChatClientBuilder(innerClient)
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(researchTools.SearchWeb),
        AIFunctionFactory.Create(researchTools.SaveNote),
        AIFunctionFactory.Create(researchTools.GetNotes),
    ]
};

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your goal is to research a topic thoroughly by:
        1. Searching the web for relevant information (make multiple searches with different queries)
        2. Saving important findings as notes
        3. Finally, retrieving all notes and providing a comprehensive summary

        Always search at least 2-3 different aspects of the topic, save key findings,
        then produce a final summary.
        """),
    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}")
};

Console.WriteLine("Agent is researching...\n");

var response = await agent.GetResponseAsync(messages, chatOptions);

Console.WriteLine("=== Research Summary ===\n");
Console.WriteLine(response.Text);
Console.WriteLine("\n=== Saved Notes ===\n");
foreach (var note in researchTools.Notes)
{
    Console.WriteLine($"• {note}");
}

// --- Tool Definitions ---

public class ResearchTools
{
    private static readonly HttpClient Http = new();
    public List<string> Notes { get; } = [];

    [Description("Search the web for information on a query. Returns a list of search result snippets.")]
    public async Task<string> SearchWeb([Description("The search query")] string query)
    {
        Console.WriteLine($"  [Tool] Searching web: \"{query}\"");

        try
        {
            // Use DuckDuckGo Instant Answer API as a free search source
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var result = await Http.GetFromJsonAsync<JsonElement>(url);

            var snippets = new List<string>();

            if (result.TryGetProperty("Abstract", out var abs) && abs.GetString() is { Length: > 0 } abstract_)
                snippets.Add($"Summary: {abstract_}");

            if (result.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var item in topics.EnumerateArray().Take(5))
                {
                    if (item.TryGetProperty("Text", out var text) && text.GetString() is { Length: > 0 } t)
                        snippets.Add(t);
                }
            }

            if (snippets.Count == 0)
                snippets.Add($"No detailed results found for '{query}'. Try a more specific query.");

            return string.Join("\n\n", snippets);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Save a research note for later reference.")]
    public string SaveNote([Description("The note content to save")] string note)
    {
        Notes.Add(note);
        Console.WriteLine($"  [Tool] Note saved ({Notes.Count} total)");
        return $"Note saved successfully. You now have {Notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        Console.WriteLine("  [Tool] Retrieving all notes");
        if (Notes.Count == 0)
            return "No notes saved yet.";
        return string.Join("\n---\n", Notes.Select((n, i) => $"Note {i + 1}: {n}"));
    }
}

